// Independent palettes. Personal appearance is separate from engineering data.
const studioThemes={
  paper:{name:'暖纸 · 工程手稿',dark:false,bg:'#f0ece3',panel:'#fffcf5',surface:'#f7f2e8',canvas:'#fffcf5',border:'#ded7c9',ink:'#383a32',muted:'#827b6e',blue:'#9b5f34',highlight:'#f2e6d3',grid:'#eae3d6',major:'#d1c5b1',waves:['#3c7280','#558267','#ad7541','#8c6f9e','#b86163','#798346']},
  graphite:{name:'石墨 · 低亮度',dark:true,bg:'#101419',panel:'#1a2028',surface:'#151b22',canvas:'#151b22',border:'#303944',ink:'#dde4ed',muted:'#98a6b7',blue:'#e2b578',highlight:'#31302c',grid:'#26303a',major:'#414c58',waves:['#85b8d3','#8bc5ad','#e2b578','#b5a4da','#df9b9f','#bfd17b']},
  ocean:{name:'深海 · 青色仪表',dark:true,bg:'#0c1a24',panel:'#112837',surface:'#0e202d',canvas:'#0e202d',border:'#254556',ink:'#d5e7ed',muted:'#8eacb9',blue:'#69c7c2',highlight:'#20434c',grid:'#1b3543',major:'#355b6b',waves:['#69c7c2','#86b7ef','#e6ba75','#c3a0dc','#e393a0','#a8c47c']},
  sage:{name:'青绿 · 柔和浅色',dark:false,bg:'#e8efeb',panel:'#f8fcf9',surface:'#eef5f0',canvas:'#f8fcf9',border:'#d4e1d8',ink:'#2a433a',muted:'#738c80',blue:'#3e806c',highlight:'#dfede3',grid:'#e3eee7',major:'#bfd3c6',waves:['#397a71','#477da2','#a57a40','#886b9e','#b9687d','#798942']},
  indigo:{name:'靛青 · 清晰白底',dark:false,bg:'#eceef5',panel:'#ffffff',surface:'#f5f6fb',canvas:'#ffffff',border:'#dbdeeb',ink:'#303b55',muted:'#7a85a0',blue:'#6268b6',highlight:'#ececfc',grid:'#e9ebf6',major:'#c9cee5',waves:['#616cc0','#328c86','#be8840','#a165ad','#c35f83','#758d46']},
  highcontrast:{name:'高对比 · 黑白',dark:false,bg:'#e8e8e8',panel:'#ffffff',surface:'#f2f2f2',canvas:'#ffffff',border:'#999999',ink:'#101010',muted:'#505050',blue:'#154b9b',highlight:'#e2eaff',grid:'#d5d5d5',major:'#777777',waves:['#003f8c','#006a4e','#8e4a00','#6e3588','#9a224d','#4d671b']}
};
let personalTheme={preset:'paper',...WC.copy(studioThemes.paper)};
try{const stored=JSON.parse(localStorage.getItem('wavecraft-appearance-v3'));if(stored&&Object.keys(studioThemes.paper).filter(k=>!['name','dark','waves'].includes(k)).every(k=>/^#[a-f\d]{6}$/i.test(stored[k])))personalTheme=stored}catch{}
function applyAppearance(theme){document.body.classList.toggle('dark',!!theme.dark);for(const key of ['bg','panel','surface','canvas','border','ink','muted','blue','highlight','grid','major'])document.body.style.setProperty('--'+key,theme[key]);document.body.style.colorScheme=theme.dark?'dark':'light';document.body.style.setProperty('--primaryink',theme.dark?'#18222b':'#ffffff');scheduleCanvas()}
applyAppearance(personalTheme);$('theme').textContent='◈ 主题';$('theme').title='预设主题与自定义颜色';
$('theme').onclick=()=>{const before=WC.copy(personalTheme);let saved=false;const keys=[['canvas','画布背景'],['panel','面板背景'],['surface','工具栏背景'],['ink','主要文字'],['muted','辅助文字'],['blue','强调色'],['grid','网格细线'],['major','标尺 / 主网格']];modal('工作台外观',`<p>外观是个人偏好，保存在当前浏览器。工程波形颜色单独保存；默认不会覆盖你已设置的信号颜色。</p><div class="themechooser"><select id="themePreset">${Object.entries(studioThemes).map(([id,t])=>`<option value="${id}" ${id===personalTheme.preset?'selected':''}>${t.name}</option>`).join('')}</select><button id="loadThemePreset">载入并预览</button></div><div class="themefields">${keys.map(([key,name])=>`<label class="field">${name}<input type="color" id="theme_${key}" value="${personalTheme[key]}"></label>`).join('')}</div><label class="check"><input type="checkbox" id="themeDark" ${personalTheme.dark?'checked':''}>深色控件</label><label class="check"><input type="checkbox" id="themeWaves">同时应用预设波形配色（修改工程，可撤销）</label><div class="themeSwatches" id="themeSwatches"></div><p>SVG / PNG / 打印保持白底，方便插入文档；波形颜色随工程输出。</p>`,()=>{let next=WC.copy(personalTheme);for(const[key]of keys)next[key]=$('theme_'+key).value;next.dark=$('themeDark').checked;next.preset=$('themePreset').value;if($('themeWaves').checked){checkpoint();doc.signals.forEach((s,i)=>s.color=next.waves[i%next.waves.length]);commit()}personalTheme=next;applyAppearance(next);try{localStorage.setItem('wavecraft-appearance-v3',JSON.stringify(next))}catch{toast('外观缓存不可用')}saved=true;toast('主题已保存')},'保存主题');const swatches=()=>$('themeSwatches').innerHTML=personalTheme.waves.map(c=>`<span style="background:${c}"></span>`).join('');swatches();$('loadThemePreset').onclick=()=>{personalTheme={preset:$('themePreset').value,...WC.copy(studioThemes[$('themePreset').value])};for(const[key]of keys)$('theme_'+key).value=personalTheme[key];$('themeDark').checked=personalTheme.dark;swatches();applyAppearance(personalTheme)};for(const[key]of keys)$('theme_'+key).oninput=()=>{let preview=WC.copy(personalTheme);for(const[k]of keys)preview[k]=$('theme_'+k).value;applyAppearance(preview)};$('dialog').addEventListener('close',()=>{if(!saved){personalTheme=before;applyAppearance(before)}},{once:true})};
